import { describe, it, expect, vi } from 'vitest';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { ChipBar } from './ChipBar';

const OPTIONS = [
  { id: 'to-read', label: 'To Read' },
  { id: 'reading', label: 'Reading' },
  { id: 'read', label: 'Read' },
];

const ALL_OPTION = { id: 'all', label: 'All' };
const OPTIONS_WITH_ALL = [ALL_OPTION, ...OPTIONS];

describe('ChipBar', () => {
  it('renders a button for each option', () => {
    render(
      <ChipBar options={OPTIONS} selected={[]} onSelectionChange={vi.fn()} />
    );
    expect(screen.getAllByRole('button')).toHaveLength(OPTIONS.length);
  });

  it('renders chip labels', () => {
    render(
      <ChipBar options={OPTIONS} selected={[]} onSelectionChange={vi.fn()} />
    );
    for (const option of OPTIONS) {
      expect(screen.getByRole('button', { name: option.label })).toBeInTheDocument();
    }
  });

  it('unselected chips have aria-pressed false', () => {
    render(
      <ChipBar options={OPTIONS} selected={[]} onSelectionChange={vi.fn()} />
    );
    for (const option of OPTIONS) {
      expect(screen.getByRole('button', { name: option.label })).toHaveAttribute(
        'aria-pressed',
        'false'
      );
    }
  });

  it('selected chips have aria-pressed true', () => {
    render(
      <ChipBar
        options={OPTIONS}
        selected={['reading']}
        onSelectionChange={vi.fn()}
      />
    );
    expect(screen.getByRole('button', { name: 'Reading' })).toHaveAttribute(
      'aria-pressed',
      'true'
    );
    expect(screen.getByRole('button', { name: 'To Read' })).toHaveAttribute(
      'aria-pressed',
      'false'
    );
  });

  it('multiple chips can be pressed simultaneously', () => {
    render(
      <ChipBar
        options={OPTIONS}
        selected={['reading', 'read']}
        onSelectionChange={vi.fn()}
      />
    );
    expect(screen.getByRole('button', { name: 'Reading' })).toHaveAttribute(
      'aria-pressed',
      'true'
    );
    expect(screen.getByRole('button', { name: 'Read' })).toHaveAttribute(
      'aria-pressed',
      'true'
    );
    expect(screen.getByRole('button', { name: 'To Read' })).toHaveAttribute(
      'aria-pressed',
      'false'
    );
  });

  it('calls onSelectionChange with chip added when an unselected chip is clicked', async () => {
    const handleChange = vi.fn();
    render(
      <ChipBar
        options={OPTIONS}
        selected={['reading']}
        onSelectionChange={handleChange}
      />
    );
    await userEvent.click(screen.getByRole('button', { name: 'To Read' }));
    expect(handleChange).toHaveBeenCalledOnce();
    expect(handleChange).toHaveBeenCalledWith(
      expect.arrayContaining(['reading', 'to-read'])
    );
  });

  it('calls onSelectionChange with chip removed when a selected chip is clicked', async () => {
    const handleChange = vi.fn();
    render(
      <ChipBar
        options={OPTIONS}
        selected={['reading', 'read']}
        onSelectionChange={handleChange}
      />
    );
    await userEvent.click(screen.getByRole('button', { name: 'Reading' }));
    expect(handleChange).toHaveBeenCalledOnce();
    const [newSelected] = handleChange.mock.calls[0];
    expect(newSelected).not.toContain('reading');
    expect(newSelected).toContain('read');
  });

  it('does not mutate the selected array — returns a new array', async () => {
    const handleChange = vi.fn();
    const selected: string[] = ['read'];
    render(
      <ChipBar
        options={OPTIONS}
        selected={selected}
        onSelectionChange={handleChange}
      />
    );
    await userEvent.click(screen.getByRole('button', { name: 'To Read' }));
    expect(handleChange.mock.calls[0][0]).not.toBe(selected);
  });

  describe('All chip', () => {
    it('All chip has aria-pressed true when nothing else is selected', () => {
      render(
        <ChipBar
          options={OPTIONS_WITH_ALL}
          selected={[]}
          onSelectionChange={vi.fn()}
        />
      );
      expect(screen.getByRole('button', { name: 'All' })).toHaveAttribute(
        'aria-pressed',
        'true'
      );
    });

    it('All chip has aria-pressed false when at least one other chip is selected', () => {
      render(
        <ChipBar
          options={OPTIONS_WITH_ALL}
          selected={['reading']}
          onSelectionChange={vi.fn()}
        />
      );
      expect(screen.getByRole('button', { name: 'All' })).toHaveAttribute(
        'aria-pressed',
        'false'
      );
    });

    it('clicking All chip calls onSelectionChange with empty array', async () => {
      const handleChange = vi.fn();
      render(
        <ChipBar
          options={OPTIONS_WITH_ALL}
          selected={['reading', 'read']}
          onSelectionChange={handleChange}
        />
      );
      await userEvent.click(screen.getByRole('button', { name: 'All' }));
      expect(handleChange).toHaveBeenCalledOnce();
      expect(handleChange).toHaveBeenCalledWith([]);
    });

    it('clicking All chip when nothing is selected calls onSelectionChange with empty array', async () => {
      const handleChange = vi.fn();
      render(
        <ChipBar
          options={OPTIONS_WITH_ALL}
          selected={[]}
          onSelectionChange={handleChange}
        />
      );
      await userEvent.click(screen.getByRole('button', { name: 'All' }));
      expect(handleChange).toHaveBeenCalledOnce();
      expect(handleChange).toHaveBeenCalledWith([]);
    });
  });
});
